// Credential EXISTENCE and channel-scoping is already enforced by
// load_publication_upload_inputs's WHERE channel_id = ... lookup (see
// database/migrations/20260722280001_youtube_publication_pipeline_functions.sql) --
// this step re-verifies STATUS defensively (belt-and-suspenders with
// youtube_publication_preflight's own credential_not_active check) and
// resolves which API base URLs this run should call. Mock vs. real
// YouTube is selected entirely by which URLs the n8n service was
// started with -- see docs/architecture/youtube-publication-pipeline.md#testing-without-real-uploads.
// Requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false (see docker-compose.yml's
// n8n service) -- n8n blocks $env access from every node by default.
const b = $input.first().json;
const youtubeApiBaseUrl = ($env.YOUTUBE_API_BASE_URL || 'https://www.googleapis.com/youtube/v3').replace(/\/$/, '');
const youtubeUploadApiBaseUrl = ($env.YOUTUBE_UPLOAD_API_BASE_URL || 'https://www.googleapis.com/upload/youtube/v3').replace(/\/$/, '');
const runtime = { channel_id: b.channel_id, workflow_run_id: b.workflow_run_id, content_project_id: b.content_project_id, correlation_id: b.correlation_id ?? null };
if (!b.youtube_credential_reference || b.youtube_credential_status !== 'active') {
  return [{ json: {
    success: false, data: null,
    error: { code: 'YOUTUBE_CREDENTIAL_NOT_CONFIGURED', message: `channel ${b.channel_id} has no active youtube_oauth credential (status: ${b.youtube_credential_status ?? 'missing'})`, retryable: false, error_id: null },
    runtime,
  } }];
}
return [{ json: {
  success: true,
  data: { youtube_credential_reference: b.youtube_credential_reference, youtube_api_base_url: youtubeApiBaseUrl, youtube_upload_api_base_url: youtubeUploadApiBaseUrl },
  error: null,
  runtime,
} }];
